function lb_subject_match(string $a,string $b):bool{$a=function_exists('tkb_subject_canonical')?tkb_subject_canonical($a):$a;$b=function_exists('tkb_subject_canonical')?tkb_subject_canonical($b):$b;return lb_same($a,$b)||(function_exists('tkb_subject_related')&&tkb_subject_related($a,$b));}
