function lb_record_before_week(array $record,array $week):bool{
 $start=trim((string)($week['start']??''));
 $date=trim((string)($record['date']??''));
 if($start!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))return $date<$start;
