    $period=max(1,(int)($registration['period']??0));$session=trim((string)($registration['session']??'Sáng'))?:'Sáng';if($class===''||$subject===''||$teacher==='')continue;
    $kind=lb_norm((string)($registration['type']??$registration['registration_type']??$registration['kind']??''));$isMakeup=str_contains($kind,'makeup')||str_contains($kind,'daybu')||empty($registration['absent_teacher']);$scheduled=$isMakeup?$teacher:(trim((string)($registration['absent_teacher']??''))?:$teacher);$base=['week_key'=>(string)$week['key'],'week_label'=>(string)$week['label'],'date'=>$regDate,'day'=>(int)date('N',strtotime($regDate))+1,'session'=>$session,'period'=>$period,'class'=>$class,'subject'=>function_exists('tkb_subject_canonical')?tkb_subject_canonical($subject):$subject,'scheduled_teacher'=>$scheduled,'actual_teacher'=>$teacher,'book_type'=>'main','grade'=>lb_grade($class),'status'=>$isMakeup?'makeup':'substitute','approved_registration_id'=>$regId];
    $base['slot_id']=lb_slot_id($week,$base);$row=array_merge($base,(array)($saved[$base['slot_id']]??[]));$out[]=$row;
}
usort($out,fn($a,$b)=>strcmp(($a['date'].'|'.$a['session'].'|'.sprintf('%03d',$a['period']).'|'.$a['class']),($b['date'].'|'.$b['session'].'|'.sprintf('%03d',$b['period']).'|'.$b['class'])));$virtual=array_values(array_filter($allRecords,fn($r)=>lb_record_before_week($r,$week)));foreach($out as&$row){$used=lb_ppct_used_periods((string)$row['class'],(string)$row['subject'],(string)$row['slot_id'],$virtual);$current=(int)($row['ppct_period']??0);if($current>0){$virtual[]=$row;$row['suggested_ppct_period']=$current;}else{$suggested=lb_ppct_next_period($used);$row['suggested_ppct_period']=$suggested;$virtual[]=array_merge($row,['ppct_period'=>$suggested,'_suggested'=>true]);}$row['used_ppct_periods']=array_values(array_map('intval',array_keys(lb_ppct_used_periods((string)$row['class'],(string)$row['subject'],(string)$row['slot_id']))));}unset($row);return$out;}
function lb_can_edit(array $row): bool {if(lb_is_admin())return true;$me=lb_teacher_name();$actual=trim((string)($row['actual_teacher']??''));$scheduled=trim((string)($row['scheduled_teacher']??''));if($actual!==''&&!lb_same($actual,$scheduled))return lb_same($me,$actual);return lb_same($me,$actual!==''?$actual:$scheduled);}
