function lb_rating_points(): array {return(array)lb_settings()['rating_points'];}
function lb_score_ranking(array $rows,string $field): array {$out=[];$points=lb_rating_points();foreach($rows as$r){$name=trim((string)($r[$field]??''));$rating=(string)($r['rating']??'');if($name===''||!isset($points[$rating]))continue;if(!isset($out[$name]))$out[$name]=['name'=>$name,'count'=>0,'total'=>0];$out[$name]['count']++;$out[$name]['total']+=(float)$points[$rating];}foreach($out as&$g)$g['average']=$g['count']?$g['total']/$g['count']:0;unset($g);$out=array_values($out);usort($out,fn($a,$b)=>$b['average']<=>$a['average']?:$b['count']<=>$a['count']?:strnatcasecmp($a['name'],$b['name']));foreach($out as$i=>&$g)$g['rank']=$i+1;unset($g);return$out;}
function lb_class_week_averages(array $rows): array {$points=lb_rating_points();$out=[];foreach($rows as$r){$rating=(string)($r['rating']??'');$class=trim((string)($r['class']??''));$week=trim((string)($r['week_key']??''));if($class===''||$week===''||!isset($points[$rating]))continue;$key=$week.'|'.lb_norm($class);if(!isset($out[$key]))$out[$key]=['week_key'=>$week,'week_label'=>(string)($r['week_label']??$week),'class'=>$class,'count'=>0,'total'=>0];$out[$key]['count']++;$out[$key]['total']+=(float)$points[$rating];}foreach($out as&$g)$g['average']=$g['count']?$g['total']/$g['count']:0;unset($g);$out=array_values($out);usort($out,fn($a,$b)=>strcmp($a['week_key'],$b['week_key'])?:strnatcasecmp($a['class'],$b['class']));return$out;}
