function lb_save_record(array $week,array $input): array {$slotId=trim((string)($input['slot_id']??''));$slot=null;foreach(lb_slots($week)as$r)if(($r['slot_id']??'')===$slotId){$slot=$r;break;}if(!$slot)return['ok'=>false,'message'=>'Không tìm thấy tiết học trong TKB tuần đã chọn.'];if(!lb_can_edit($slot))return['ok'=>false,'message'=>'Bạn không được nhập tiết học này.'];if(lb_locked($week,$slot))return['ok'=>false,'message'=>'Sổ của lớp này đã khóa.'];$allowedStatus=['pending','taught','substitute','makeup','online','holiday','teacher_absent','class_absent','postponed','cancelled'];$status=(string)($input['status']??'taught');if(!in_array($status,$allowedStatus,true))$status='taught';$rating=(string)($input['rating']??'');if(!in_array($rating,['','Tốt','Khá','Trung bình','Yếu'],true))$rating='';$bookType=in_array((string)($input['book_type']??'main'),['main','session2'],true)?(string)$input['book_type']:'main';$changes=['book_type'=>$bookType,'ppct_period'=>max(0,(int)($input['ppct_period']??0)),'lesson_title'=>trim((string)($input['lesson_title']??'')),'absent_names'=>trim((string)($input['absent_names']??'')),'teacher_comment'=>trim((string)($input['teacher_comment']??'')),'rating'=>$rating,'status'=>$status,'actual_teacher'=>trim((string)($slot['actual_teacher']??''))?:trim((string)($slot['scheduled_teacher']??'')),'actual_periods'=>max(0,(float)($input['actual_periods']??1)),'updated_at'=>date('c'),'updated_by'=>lb_teacher_name()];if($changes['ppct_period']&&$changes['lesson_title']===''){$c=lb_curriculum_for((string)$slot['subject'],(string)$slot['grade'],$changes['ppct_period']);if($c)$changes['lesson_title']=(string)($c['title']??'');}if(in_array($status,['taught','substitute','makeup','online'],true)&&$changes['ppct_period']>0){$used=lb_ppct_used_periods((string)$slot['class'],(string)$slot['subject'],$slotId);$period=(int)$changes['ppct_period'];if(isset($used[$period])){$old=$used[$period];return['ok'=>false,'message'=>'Tiết PPCT '.$period.' môn '.$slot['subject'].' lớp '.$slot['class'].' đã được nhập'.(!empty($old['date'])?' ngày '.date('d/m/Y',strtotime((string)$old['date'])):'').'.'];}if($period>1&&!isset($used[$period-1]))return['ok'=>false,'message'=>'Chưa thể nhập tiết PPCT '.$period.': môn '.$slot['subject'].' lớp '.$slot['class'].' chưa có tiết '.($period-1).'.'];}$missing=[];if($status==='pending')$missing[]='trạng thái hoàn thành';if(in_array($status,['taught','substitute','makeup','online'],true)){if(trim((string)$changes['actual_teacher'])==='')$missing[]='giáo viên thực tế';if((int)$changes['ppct_period']<1)$missing[]='tiết PPCT';if(trim((string)$changes['lesson_title'])==='')$missing[]='đầu bài/nội dung';if($changes['rating']==='')$missing[]='xếp loại';if((float)$changes['actual_periods']<=0)$missing[]='số tiết thực tế';}if($missing)return['ok'=>false,'message'=>'Chưa thể lưu tiết '.$slot['period'].' lớp '.$slot['class'].': còn thiếu '.implode(', ',$missing).'.'];$records=lb_rows(LB_RECORDS_FILE);$found=false;foreach($records as&$r)if(($r['slot_id']??'')===$slotId){$r=array_merge($r,$slot,$changes);$found=true;break;}unset($r);if(!$found)$records[]=array_merge($slot,$changes,['created_at'=>date('c')]);if(!lb_write(LB_RECORDS_FILE,$records))return['ok'=>false,'message'=>'Không lưu được sổ đầu bài. Dữ liệu cũ được giữ nguyên.'];lb_audit('save_record',['slot_id'=>$slotId,'status'=>$status]);return['ok'=>true,'message'=>'Đã lưu sổ đầu bài. Tiết này chỉ được tính hoàn thành sau khi giáo viên ký.'];}
function lb_save_and_sign(array $week,array $input):array{$sig=lb_signature_meta();if(!$sig)return['ok'=>false,'message'=>'Bạn chưa có ảnh chữ ký. Hãy vào tab Chữ ký, tải chữ ký lên rồi thực hiện Ký tiết học.'];$saved=lb_save_record($week,$input);if(empty($saved['ok']))return$saved;return lb_sign($week,(string)($input['slot_id']??''));}
