function lb_sign(array $week,string $slotId): array {foreach(lb_slots($week)as$row)if(($row['slot_id']??'')===$slotId){if(!lb_can_edit($row))return['ok'=>false,'message'=>'Bạn không được ký tiết này.'];if(lb_locked($week,$row))return['ok'=>false,'message'=>'Sổ đã khóa.'];$sig=lb_signature_meta();if(!$sig)return['ok'=>false,'message'=>'Bạn chưa có ảnh chữ ký. Hãy tải chữ ký lên trước khi ký tiết học.'];$records=lb_rows(LB_RECORDS_FILE);foreach($records as&$r)if(($r['slot_id']??'')===$slotId){$r['signed_at']=date('c');$r['signed_by']=lb_teacher_name();$r['signature_path']=$sig['path'];$r['signature_version']=$sig['version'];if(!lb_write(LB_RECORDS_FILE,$records))return['ok'=>false,'message'=>'Không lưu được chữ ký tiết học.'];lb_audit('sign_record',['slot_id'=>$slotId,'signature_version'=>$sig['version'],'signed_by'=>lb_teacher_name()]);return['ok'=>true,'message'=>'Đã lưu nội dung, gán chữ ký và họ tên giáo viên.'];}return['ok'=>false,'message'=>'Không tìm thấy nội dung vừa lưu để ký.'];}return['ok'=>false,'message'=>'Không tìm thấy tiết học.'];}
function lb_save_curriculum(array $in): array {if(!lb_is_admin())return['ok'=>false,'message'=>'Chỉ quản trị được sửa PPCT.'];$subject=trim((string)($in['subject']??''));$grade=preg_replace('/\D+/','',trim((string)($in['grade']??'')));$period=(int)($in['period']??0);$title=trim((string)($in['title']??''));if($subject===''||$grade===''||$period<1||$title==='')return['ok'=>false,'message'=>'Nhập đủ môn, khối, tiết PPCT và tên bài.'];$rows=lb_curriculum();$found=false;foreach($rows as&$r)if(lb_same((string)($r['subject']??''),$subject)&&(string)$r['grade']===$grade&&(int)$r['period']===$period){$r=array_merge($r,['subject'=>$subject,'grade'=>$grade,'period'=>$period,'title'=>$title]);$found=true;break;}unset($r);if(!$found)$rows[]=['id'=>lb_id('ppct'),'subject'=>$subject,'grade'=>$grade,'period'=>$period,'title'=>$title];lb_write(LB_CURRICULUM_FILE,$rows);return['ok'=>true,'message'=>'Đã lưu PPCT.'];}
