 $headerRow=0;$columns=[];$required=['stt','grade','subject','period','title','order','semester'];
 $aliases=['stt'=>'stt','tenkhoi'=>'grade','khoi'=>'grade','khoilop'=>'grade','tenmonhoc'=>'subject','monhoc'=>'subject','mon'=>'subject','tiettheoppct'=>'period','tietppct'=>'period','ppct'=>'period','tenbaiday'=>'title','tenbai'=>'title','tenbainoidung'=>'title','thutu'=>'order','hocky'=>'semester'];
 foreach((array)$raw['rows']as$n=>$row){$found=[];foreach($row as$col=>$value){$key=lb_norm((string)$value);if(isset($aliases[$key]))$found[$aliases[$key]]=(int)$col;}if(count(array_intersect($required,array_keys($found)))===7){$headerRow=(int)$n;$columns=$found;break;}}
 if(!$headerRow)return['ok'=>false,'message'=>'Sai cấu trúc tệp PPCT. Cần đủ 7 cột: STT, Tên khối, Tên môn học, Tiết theo PPCT, Tên bài dạy, Thứ tự, Học kỳ. Vui lòng dùng đúng mẫu Excel của hệ thống.'];
 $incoming=[];$errors=[];$warnings=[];$seen=[];
 foreach((array)$raw['rows']as$n=>$row){if((int)$n<=$headerRow)continue;$sttRaw=trim((string)($row[$columns['stt']]??''));$gradeRaw=trim((string)($row[$columns['grade']]??''));$subject=trim((string)($row[$columns['subject']]??''));$periodRaw=trim((string)($row[$columns['period']]??''));$title=trim((string)($row[$columns['title']]??''));$orderRaw=trim((string)($row[$columns['order']]??''));$semesterRaw=trim((string)($row[$columns['semester']]??''));if($sttRaw===''&&$gradeRaw===''&&$subject===''&&$periodRaw===''&&$title===''&&$orderRaw===''&&$semesterRaw==='')continue;$rowErrors=[];$grade=preg_replace('/\D+/','',$gradeRaw);if(!is_numeric($sttRaw)||(int)$sttRaw<1)$rowErrors[]='STT không hợp lệ';if($grade===''||(int)$grade<6||(int)$grade>12)$rowErrors[]='Tên khối phải từ Khối 6 đến Khối 12';if($subject==='')$rowErrors[]='thiếu Tên môn học';if(!is_numeric($periodRaw)||(int)$periodRaw<1)$rowErrors[]='Tiết theo PPCT không hợp lệ';if($title==='')$rowErrors[]='thiếu Tên bài dạy';if(!is_numeric($orderRaw)||(int)$orderRaw<1)$rowErrors[]='Thứ tự không hợp lệ';if(!in_array((int)$semesterRaw,[1,2],true))$rowErrors[]='Học kỳ chỉ nhận 1 hoặc 2';if($rowErrors){$errors[]='Dòng '.$n.': '.implode(', ',$rowErrors).'.';continue;}$period=(int)$periodRaw;$order=(int)$orderRaw;$semester=(int)$semesterRaw;$key=lb_norm($subject).'|'.$grade.'|'.$period;if(isset($seen[$key])){$errors[]='Dòng '.$n.': trùng Môn + Khối + Tiết PPCT với dòng '.$seen[$key].'.';continue;}$seen[$key]=$n;if($period!==$order)$warnings[]='Dòng '.$n.': Tiết theo PPCT ('.$period.') khác Thứ tự ('.$order.').';$incoming[$key]=['stt'=>(int)$sttRaw,'subject'=>$subject,'grade'=>$grade,'grade_name'=>'Khối '.$grade,'period'=>$period,'title'=>$title,'order'=>$order,'semester'=>$semester];}
